<script lang="ts">
 import RuntimeWidget from './RuntimeWidget.svelte';import type {WidgetValues} from '$lib/widgets';
 import {onMount} from 'svelte';import {localization} from '$lib/localization';
 import DetailModal from '../DetailModal.svelte';
 import WidgetContent from './WidgetContent.svelte';import WidgetLink from './WidgetLink.svelte';import WorldClock from './WorldClock.svelte';
 import {widgetText,widgetDimensions,type WidgetDefinition,type WidgetSize,type WidgetData,type DataItem} from '$lib/widgets';
 let {definition,size,data,note='',clockDesign='digital',scale=1,expandedView=false,measureOnly=false,previewOnly=false,configuration={},initialRecords=[],instanceKey}: {definition:WidgetDefinition;size:WidgetSize;data:WidgetData;note?:string;clockDesign?:string;scale?:number;expandedView?:boolean;measureOnly?:boolean;previewOnly?:boolean;configuration?:WidgetValues;initialRecords?:Array<{recordKey:string;values:WidgetValues}>;instanceKey?:string}=$props();
 let lang:'ja'|'en'=$derived($localization.displayLanguage==='ja'?'ja':'en');let t=$derived(widgetText[lang]);
 let now=$state(new Date());let expanded=$state(false);let returnFocus=$state<HTMLElement|null>(null);let dimensions=$derived(widgetDimensions(definition,size));let showClockSeconds=$derived(dimensions.rows*dimensions.columns>=6);let limit=$derived(expandedView?500:3);let clockGrid=$state<HTMLDivElement>();let clockWidth=$state(190);let cityPage=$state(0);let clocks=$derived(data.world_clock??['Asia/Tokyo']);let clockItemWidth=$derived(210*scale);let capacity=$derived(Math.max(1,Math.floor((clockWidth+12)/(clockItemWidth+12))));let paging=$derived(clocks.length>capacity);let pageCount=$derived(Math.max(1,Math.floor((clockWidth-(paging?64:0)+12)/(clockItemWidth+12))));let lastCity=$derived(Math.max(0,clocks.length-pageCount));let cityStart=$derived(Math.min(cityPage,lastCity));
 function more(event:MouseEvent){returnFocus=event.currentTarget as HTMLElement;expanded=true;}
 onMount(()=>{if(!clockGrid)return;const observer=new ResizeObserver(entries=>clockWidth=entries[0].contentRect.width);observer.observe(clockGrid);return()=>observer.disconnect();});
 onMount(()=>{if(measureOnly||!definition.capabilities.includes('world_clock'))return;const id=setInterval(()=>now=new Date(),1000);return()=>clearInterval(id);});
 function items(key:string|undefined):DataItem[]{return key==='account'?data.account??[]:key==='book_loans'?data.book_loans??[]:key==='book_notices'?data.book_notices??[]:[];}
</script>
<div class="widget-content" class:clock-content={definition.view.length===1&&['runtime','clock','calculator','programmer_calculator','timer','stopwatch','unit_converter','personal_note'].includes(definition.view[0].type)&&!previewOnly&&!measureOnly&&!expandedView} style={`--widget-scale:${scale};font-size:${scale}rem`}>
{#each definition.view as block}
 {#if block.type==='runtime'}<RuntimeWidget {definition} {instanceKey} {configuration} records={initialRecords} preview={previewOnly} expanded={expandedView} {measureOnly} {size} {scale}/>{:else if block.type==='text'}<p>{block.text?.[lang]}</p>
 {:else if block.type==='number'}<strong class="number">{block.value}</strong>
 {:else if block.type==='date'}<p>{data.date}</p>
 {:else if block.type==='link' && block.href}{#if previewOnly}<span>{block.text?.[lang]??''}</span>{:else}<WidgetLink href={block.href} label={block.text?.[lang]??''}/>{/if}
 {:else if block.type==='clock'}<div bind:this={clockGrid} class="clocks-wrap" class:preview-clocks={previewOnly||measureOnly}><div class="clocks" class:paging>{#each clocks.slice(cityStart,cityStart+pageCount) as zone}<WorldClock {zone} {now} {lang} showSeconds={showClockSeconds} design={clockDesign} compact={paging}/>{/each}</div>
 {#if paging}<button class="clock-nav previous-city" type="button" disabled={cityStart===0} onclick={()=>cityPage=Math.max(0,cityStart-1)} aria-label={lang==='ja'?'前の時計':'Previous clock'}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 6-6 6 6 6"/></svg></button><button class="clock-nav next-city" type="button" disabled={cityStart===lastCity} onclick={()=>cityPage=Math.min(lastCity,cityStart+1)} aria-label={lang==='ja'?'次の時計':'Next clock'}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></button>{/if}</div>
 {:else if block.type==='records'}<div class="records-preview"><p>{lang==='ja'?'保存データの一覧・追加・編集':'View, add and edit saved records'}</p>{#each definition.storage?.listFields??[] as field}<p>{definition.storage?.fields[field].label[lang]}</p>{/each}</div>
 {:else if block.type==='list'}
  {#if items(block.data).length}<ul class:summary-list={!expandedView}>{#each items(block.data).slice(0,limit) as item}<li>{#if item.href&&!previewOnly}<WidgetLink href={item.href} label={item.name}/>{:else}{item.name}{/if}{#if item.date}<small>{item.date}{item.kind?' · '+(item.kind==='overdue'?t.overdue:t.dueSoon):''}</small>{/if}</li>{/each}</ul>{#if items(block.data).length>limit&&!expandedView}<button type="button" disabled={previewOnly||measureOnly} onclick={more}>{t.more}</button>{/if}{:else}<p>{t.empty}</p>{/if}
 {/if}
{/each}
</div>
{#if expanded}<DetailModal title={definition.name[lang]} titleId="widget-content-detail" closeLabel={t.cancel} {returnFocus} onClose={()=>expanded=false}><WidgetContent {definition} {size} {data} {note} {clockDesign} expandedView={true}/></DetailModal>{/if}
<style>
 .widget-content{display:flow-root;min-width:0}.clock-content{height:100%}.widget-content :global(.app-modal-backdrop){font-size:1rem;--widget-scale:1}.summary-list li{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;line-clamp:3;overflow:hidden}.summary-list :global(.detail-link){display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;overflow:hidden}.summary-list{margin:6px 0}.summary-list li{line-height:1.4}p{margin:6px 0;color:var(--muted)}ul{margin:8px 0;padding-left:20px}li{margin:6px 0;line-height:1.6;overflow-wrap:anywhere}small{display:block;color:var(--muted);font-size:.875em;overflow-wrap:anywhere}.clocks-wrap{position:relative;height:100%;min-height:calc(218px*var(--widget-scale))}.clocks-wrap.preview-clocks,.preview-clocks .clocks{height:auto}.clocks.paging{padding-inline:32px}.clock-nav{position:absolute;top:50%;transform:translateY(-50%);width:32px;padding:4px;border:0;background:transparent;color:var(--action-primary);cursor:pointer}.clock-nav:disabled{opacity:.3;cursor:default}.clock-nav svg{width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.previous-city{left:0}.next-city{right:0}.clocks{display:flex;align-items:center;justify-content:center;gap:12px;height:100%;min-height:calc(218px*var(--widget-scale))}.clocks :global(.clock-container){flex:0 1 calc(210px*var(--widget-scale));width:calc(210px*var(--widget-scale));max-width:100%;min-width:0}.number{font-size:2.5em}button{border:1px solid var(--border);background:var(--surface);color:var(--text);border-radius:6px;padding:8px 12px;font:inherit;min-height:44px}
</style>
